import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <vector>

__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int kD, int kH, int kW,
    int sD, int sH, int sW,
    int pD, int pH, int pW,
    int groups, bool has_bias)
{
    long long total = (long long)N * C_out * D_out * H_out * W_out;
    long long tid = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    long long gstride = (long long)gridDim.x * blockDim.x;

    int cpg = C_in / groups;    // input channels per group
    int ocpg = C_out / groups;  // output channels per group

    for (long long idx = tid; idx < total; idx += gstride) {
        // Decode linear index -> (n, oc, d, h, w)
        int w = (int)(idx % W_out);
        long long t = idx / W_out;
        int h = (int)(t % H_out);
        t /= H_out;
        int d = (int)(t % D_out);
        t /= D_out;
        int oc = (int)(t % C_out);
        int n = (int)(t / C_out);

        int group = oc / ocpg;
        int oc_local = oc - group * ocpg;

        float acc = has_bias ? bias[oc] : 0.0f;

        for (int ic0 = 0; ic0 < cpg; ++ic0) {
            int ic = group * cpg + ic0;
            const float* wgt_base = weight + (((long long)ic * ocpg + oc_local) * kD) * kH * kW;
            for (int kd = 0; kd < kD; ++kd) {
                int di_num = d + pD - kd;
                if (di_num % sD != 0) continue;
                int di = di_num / sD;
                if (di < 0 || di >= D_in) continue;
                for (int kh = 0; kh < kH; ++kh) {
                    int hi_num = h + pH - kh;
                    if (hi_num % sH != 0) continue;
                    int hi = hi_num / sH;
                    if (hi < 0 || hi >= H_in) continue;
                    for (int kw = 0; kw < kW; ++kw) {
                        int wi_num = w + pW - kw;
                        if (wi_num % sW != 0) continue;
                        int wi = wi_num / sW;
                        if (wi < 0 || wi >= W_in) continue;

                        float iv = input[(((long long)(n * C_in + ic) * D_in + di) * H_in + hi) * W_in + wi];
                        float wv = wgt_base[(kd * kH + kh) * kW + kw];
                        acc += iv * wv;
                    }
                }
            }
        }
        output[idx] = acc;
    }
}

torch::Tensor conv_transpose3d(torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
                               std::vector<int64_t> stride, std::vector<int64_t> padding,
                               std::vector<int64_t> output_padding, int64_t groups)
{
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "only float32 supported");

    int64_t N = input.size(0);
    int64_t C_in = input.size(1);
    int64_t D_in = input.size(2);
    int64_t H_in = input.size(3);
    int64_t W_in = input.size(4);

    int64_t C_out_total = weight.size(1) * groups;
    int64_t kD = weight.size(2);
    int64_t kH = weight.size(3);
    int64_t kW = weight.size(4);

    int64_t sD = stride[0], sH = stride[1], sW = stride[2];
    int64_t pD = padding[0], pH = padding[1], pW = padding[2];
    int64_t opD = output_padding[0], opH = output_padding[1], opW = output_padding[2];

    int64_t D_out = (D_in - 1) * sD - 2 * pD + kD + opD;
    int64_t H_out = (H_in - 1) * sH - 2 * pH + kH + opH;
    int64_t W_out = (W_in - 1) * sW - 2 * pW + kW + opW;

    auto output = torch::empty({N, C_out_total, D_out, H_out, W_out}, input.options());

    bool has_bias = (bias.numel() > 0);

    long long total = (long long)N * C_out_total * D_out * H_out * W_out;
    int block = 256;
    long long grid = (total + block - 1) / block;
    long long max_grid = 4096;
    if (grid > max_grid) grid = max_grid;

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    conv_transpose3d_kernel<<<(int)grid, block, 0, stream>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        (int)N, (int)C_in, (int)D_in, (int)H_in, (int)W_in,
        (int)C_out_total, (int)D_out, (int)H_out, (int)W_out,
        (int)kD, (int)kH, (int)kW,
        (int)sD, (int)sH, (int)sW,
        (int)pD, (int)pH, (int)pW,
        (int)groups, has_bias);

    return output;
}
"""

_cpp_src = r"""
#include <torch/extension.h>
#include <vector>
torch::Tensor conv_transpose3d(torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
                               std::vector<int64_t> stride, std::vector<int64_t> padding,
                               std::vector<int64_t> output_padding, int64_t groups);
"""

_mod = load_inline(
    name="conv_transpose3d_custom_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["conv_transpose3d"],
    verbose=False,
    extra_cuda_cflags=["-O3"],
)


class ModelNew(nn.Module):
    """
    Transposed 3D convolution implemented with a custom CUDA kernel.
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0),
                 output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels, kernel_size, stride=stride,
            padding=padding, output_padding=output_padding,
            groups=groups, bias=bias)
        self.stride = tuple(stride)
        self.padding = tuple(padding)
        self.output_padding = tuple(output_padding)
        self.groups = groups

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        weight = self.conv_transpose3d.weight
        bias = self.conv_transpose3d.bias
        if bias is None:
            bias = torch.empty(0, device=x.device, dtype=x.dtype)
        return _mod.conv_transpose3d(
            x.contiguous(), weight.contiguous(), bias.contiguous(),
            list(self.stride), list(self.padding), list(self.output_padding),
            self.groups)

